471	void DefaultBtInteractive::checkActiveInteraction()
472	{
473	  auto inactiveTime = inactiveTimer_.difference(global::wallclock());
474	  // To allow aria2 to accept mutially interested peer, disconnect uninterested
475	  // peer.
476	  {
477	    const time_t interval = 30;
478	    if (!peer_->amInterested() && !peer_->peerInterested() &&
479	        inactiveTime >= std::chrono::seconds(interval)) {
480	      peer_->setDisconnectedGracefully(true);
481	      // TODO change the message
482	      throw DL_ABORT_EX(
483	          fmt("Disconnect peer because we are not interested each other"
484	              " after %ld second(s).",
485	              static_cast<long int>(interval)));
486	    }
487	  }
488	  // Since the peers which are *just* connected and do nothing to improve
489	  // mutual download progress are completely waste of resources, those peers
490	  // are disconnected in a certain time period.
491	  {
492	    const time_t interval = 60;
493	    if (inactiveTime >= std::chrono::seconds(interval)) {
494	      peer_->setDisconnectedGracefully(true);
495	      throw DL_ABORT_EX(
496	          fmt(EX_DROP_INACTIVE_CONNECTION, static_cast<long int>(interval)));
497	    }
498	  }
499	  // If both of us are seeders, drop connection.
500	  if (peer_->isSeeder() && pieceStorage_->downloadFinished()) {
501	    throw DL_ABORT_EX(MSG_GOOD_BYE_SEEDER);
502	  }
503	}
504	
505	void DefaultBtInteractive::addPeerExchangeMessage()
506	{
507	  if (pexTimer_.difference(global::wallclock()) >=
508	      UTPexExtensionMessage::DEFAULT_INTERVAL) {
509	    auto m = make_unique<UTPexExtensionMessage>(
510	        peer_->getExtensionMessageID(ExtensionMessageRegistry::UT_PEX));
511	    auto& usedPeers = peerStorage_->getUsedPeers();
512	    for (auto i = std::begin(usedPeers), eoi = std::end(usedPeers);
513	         i != eoi && !m->freshPeersAreFull(); ++i) {
514	      if ((*i)->isActive() && peer_->getIPAddress() != (*i)->getIPAddress()) {
515	        m->addFreshPeer(*i);
516	      }
517	    }
518	    auto& droppedPeers = peerStorage_->getDroppedPeers();
519	    for (auto i = std::begin(droppedPeers), eoi = std::end(droppedPeers);
520	         i != eoi && !m->droppedPeersAreFull(); ++i) {
521	      if (peer_->getIPAddress() != (*i)->getIPAddress()) {
522	        m->addDroppedPeer(*i);
523	      }
524	    }
525	    dispatcher_->addMessageToQueue(
526	        messageFactory_->createBtExtendedMessage(std::move(m)));
527	    pexTimer_ = global::wallclock();
528	  }
529	}
530	
531	void DefaultBtInteractive::doInteractionProcessing()
532	{
533	  if (metadataGetMode_) {
534	    sendKeepAlive();
535	    numReceivedMessage_ = receiveMessages();
536	    // PieceStorage is re-initialized with metadata_size in
537	    // HandshakeExtensionMessage::doReceivedAction().
538	    pieceStorage_ = downloadContext_->getOwnerRequestGroup()->getPieceStorage();
539	    if (peer_->getExtensionMessageID(ExtensionMessageRegistry::UT_METADATA) &&
540	        downloadContext_->getTotalLength() > 0) {
541	      size_t num = utMetadataRequestTracker_->avail();
542	      if (num > 0) {
543	        auto requests =
544	            utMetadataRequestFactory_->create(num, pieceStorage_.get());
545	        for (auto& i : requests) {
546	          dispatcher_->addMessageToQueue(std::move(i));
547	        }
548	      }
549	      if (perSecTimer_.difference(global::wallclock()) >= 1_s) {
550	        perSecTimer_ = global::wallclock();
551	        // Drop timeout request after queuing message to give a chance
552	        // to other connection to request piece.
553	        auto indexes = utMetadataRequestTracker_->removeTimeoutEntry();
554	        for (auto idx : indexes) {
555	          pieceStorage_->cancelPiece(pieceStorage_->getPiece(idx), cuid_);
556	        }
557	      }
558	      if (pieceStorage_->downloadFinished()) {
559	        downloadContext_->getOwnerRequestGroup()->setForceHaltRequested(
560	            true, RequestGroup::NONE);
561	      }
562	    }
563	  }
564	  else {
565	    checkActiveInteraction();
566	    if (perSecTimer_.difference(global::wallclock()) >= 1_s) {
567	      perSecTimer_ = global::wallclock();
568	      dispatcher_->checkRequestSlotAndDoNecessaryThing();
569	    }
570	    numReceivedMessage_ = receiveMessages();
571	    detectMessageFlooding();
572	    decideChoking();
573	    decideInterest();
574	    checkHave();
575	    sendKeepAlive();
576	    btRequestFactory_->removeCompletedPiece();
577	    if (!pieceStorage_->downloadFinished()) {
578	      addRequests();
579	    }
580	  }
581	  if (peer_->getExtensionMessageID(ExtensionMessageRegistry::UT_PEX) &&
582	      utPexEnabled_) {
583	    addPeerExchangeMessage();
584	  }
585	
586	  sendPendingMessage();
587	}
